import{_ as s,a0 as n,w as o,s as p,I as l,x as a,a1 as i,A as r,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Gamerzilla 分享你的遊戲成就 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Gamerzilla 分享你的遊戲成就 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Gamerzilla 分享你的遊戲成就 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Gamerzilla 分享你的遊戲成就 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230925 Share your game achievements with Gamerzilla","title":"使用 Gamerzilla 分享你的遊戲成就","tag":"202310","desc":""},"relativePath":"202310/20230925 Share your game achievements with Gamerzilla.md","filePath":"[post].md"}'),d={name:"202310/20230925 Share your game achievements with Gamerzilla.md"};function u(g,e,f,h,b,z){const t=n("Link");return o(),p("div",null,[e[27]||(e[27]=l("h1",{id:"使用-gamerzilla-分享你的遊戲成就",tabindex:"-1"},[a("使用 Gamerzilla 分享你的遊戲成就 "),l("a",{class:"header-anchor",href:"#使用-gamerzilla-分享你的遊戲成就","aria-label":"Permalink to “使用 Gamerzilla 分享你的遊戲成就”"},"​")],-1)),e[28]||(e[28]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202310/08/191724uj7mmjw9ccd7pcl9.jpg",alt:""})],-1)),e[29]||(e[29]=l("p",null,"Gamerzilla 是一個開源遊戲成就係統，用於存儲和共享你的遊戲成就。遊戲使用 libgamerzilla 輕鬆添加成就。Gamerzilla 庫是用 C 編寫的，但也有其他語言的綁定。",-1)),l("p",null,[e[1]||(e[1]=a("兩年前，我描述瞭如何設置 ",-1)),i(t,{href:"https://linux.cn/article-15389-1.html"},{default:r(()=>[...e[0]||(e[0]=[a("Gamerzilla 服務器",-1)])]),_:1}),e[2]||(e[2]=a("。除了 .net 實現之外，還可以使用 php 和 python 實現。但你可能不想運行自己的服務器。這裏介紹一個公共服務器和 Gnome 界面。",-1))]),e[30]||(e[30]=l("h3",{id:"公共服務器",tabindex:"-1"},[a("公共服務器 "),l("a",{class:"header-anchor",href:"#公共服務器","aria-label":"Permalink to “公共服務器”"},"​")],-1)),l("p",null,[e[4]||(e[4]=a("我的網絡服務器現在託管了一個啓用了公共註冊的 ",-1)),i(t,{href:"https://identicalsoftware.com/trophy/"},{default:r(()=>[...e[3]||(e[3]=[a("Gamerzilla",-1)])]),_:1}),e[5]||(e[5]=a(" 實例。要創建帳户，請單擊右上角的 “",-1)),e[6]||(e[6]=l("ruby",null,[a("簽到"),l("rt",null,"Sign In")],-1)),e[7]||(e[7]=a("” 鏈接。然後單擊 “",-1)),e[8]||(e[8]=l("ruby",null,[a("登錄"),l("rt",null,"Login")],-1)),e[9]||(e[9]=a("” 按鈕旁邊的 “",-1)),e[10]||(e[10]=l("ruby",null,[a("註冊"),l("rt",null,"Register")],-1)),e[11]||(e[11]=a("” 鏈接。",-1))]),e[31]||(e[31]=m('<p>用户帳户收集的信息非常少。只需輸入用户名和密碼。你不需要輸入你的真實姓名或電子郵件地址。因此，忘記密碼沒有實現。</p><p>賬户一開始是不可見的。如果你希望公眾在登錄後看到你的成就，請單擊頁面右上角你的用户名，然後選擇 “<ruby>設為可見<rt>Make Visible</rt></ruby>”。新用户必須經過批准才能上傳成就。目前沒有顯示你是否獲得批准的指示。</p><h3 id="獲得成就" tabindex="-1">獲得成就 <a class="header-anchor" href="#獲得成就" aria-label="Permalink to “獲得成就”">​</a></h3><p>在獲得第一個成就之前，你需要使用以下命令安裝 Gamerzilla GNOME Shell 擴展：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install gnome-shell-extension</span></span></code></pre></div><p>安裝後，你需要註銷並重新登錄。需要使用以下命令啓用擴展：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gnome-extensions enable gamerzilla@gamerzilla.identicalsoftware.com</span></span></code></pre></div><p>遊戲控制器圖標出現在 GNOME Shell 的頂部欄中。</p><p>單擊控制器圖標並選擇 “<ruby>首選項<rt>preferences</rt></ruby>”。在出現的屏幕上輸入你的 Gamerzilla 網址，包括尾部斜槓，但不包含 UI 的“獎盃”地址。如果使用我的服務器，該值將為 <code>https://identicalsoftware.com/</code>。填寫你的用户名和密碼。單擊保存。默認情況下啓用自動連接。如果你不想始終連接，請禁用此功能。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2023/09/gamerzilla_preferences.png" alt="Gamerzilla Controller menu"></p><p>不幸的是，一個錯誤阻止了該 Shell 擴展立即工作。你需要註銷並重新登錄。解決這個問題是當務之急。</p><h3 id="目前支持的遊戲" tabindex="-1">目前支持的遊戲 <a class="header-anchor" href="#目前支持的遊戲" aria-label="Permalink to “目前支持的遊戲”">​</a></h3><p>Fedora 倉庫中的多個遊戲支持 Gamerzilla 成就。如果你想買一個來嘗試一下，我建議試試 Shippy 1984、Seahorse Adventures 或 Anagramarama。一旦你完成一個級別，Seahorse Adventures 就會存儲一些進度。如果你玩 Super Tux Kart，你可能已經取得了成就。只需啓動遊戲即可同步之前完成的任何成就。當成就完成時，Gamerzilla 不會顯示任何通知，但遊戲可能會自行實現。</p><h3 id="更進一步" tabindex="-1">更進一步 <a class="header-anchor" href="#更進一步" aria-label="Permalink to “更進一步”">​</a></h3><p>除了修復第一次連接的錯誤之外，我還想要一個本地瀏覽器來查看成就。這樣你就可以查看所有遊戲成就，而無需強制上傳它們。</p><p>成就確實有消極的一面。有些人覺得有必要完成它們。如果成就非常困難，這可能會導致負面的遊戲體驗。我理解這種擔憂，但有些人也喜歡這些方面。更重要的是，為了吸引和留住玩家，我覺得開源遊戲需要一個遊戲成就係統。</p><p>我們需要更多遊戲來實現 Gamerzilla 成就。我們需要玩家表現出對這個系統的支持。我繼續為我的遊戲和我嘗試的其他開源遊戲添加成就。</p><p><em>（題圖：MJ/32ae3f54-b319-4db7-b874-eeacd1dcc4d2）</em></p><hr>',19)),l("p",null,[e[13]||(e[13]=a("via: ",-1)),i(t,{href:"https://fedoramagazine.org/share-your-game-achievements-with-gamerzilla/"},{default:r(()=>[...e[12]||(e[12]=[a("https://fedoramagazine.org/share-your-game-achievements-with-gamerzilla/",-1)])]),_:1})]),l("p",null,[e[18]||(e[18]=a("作者：",-1)),i(t,{href:"https://fedoramagazine.org/author/dulsi/"},{default:r(()=>[...e[14]||(e[14]=[a("Dennis Payne",-1)])]),_:1}),e[19]||(e[19]=a(" 選題：",-1)),i(t,{href:"https://github.com/lujun9972"},{default:r(()=>[...e[15]||(e[15]=[a("lujun9972",-1)])]),_:1}),e[20]||(e[20]=a(" 譯者：",-1)),i(t,{href:"https://github.com/geekpi"},{default:r(()=>[...e[16]||(e[16]=[a("geekpi",-1)])]),_:1}),e[21]||(e[21]=a(" 校對：",-1)),i(t,{href:"https://github.com/wxy"},{default:r(()=>[...e[17]||(e[17]=[a("wxy",-1)])]),_:1})]),l("p",null,[e[24]||(e[24]=a("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[22]||(e[22]=[a("LCTT",-1)])]),_:1}),e[25]||(e[25]=a(" 原創編譯，",-1)),i(t,{href:"https://linux.cn/"},{default:r(()=>[...e[23]||(e[23]=[a("Linux中國",-1)])]),_:1}),e[26]||(e[26]=a(" 榮譽推出",-1))])])}const G=s(d,[["render",u]]);export{y as __pageData,G as default};
